@startuml

class Artist {
  + Name : string
  + DateOfBirth : date
  + WebsiteURL : string
}

class Song {
  + Title : string
  + Year : int
  + Length : int
  + Genre : string
}

class User {
  + ID : int
  + Name : string
  + Address : string
}

class RegularUser extends User {}

class BusinessUser extends User {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
}

class AlbumTrack {
  + TrackNumber : int
}

class Suggestion {
}

Artist "1" -- "*" Song : belongs to
BusinessUser "1" -- "*" Song : uploads
RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : composes
Album "1" *-- "1..*" AlbumTrack : contains
AlbumTrack "*" -- "1" Hit : refers to
RegularUser "1" -- "0..*" Suggestion : suggests
RegularUser "1" -- "0..*" Suggestion : receives

@enduml

